// CreateSubscriptionJSONBody defines parameters for CreateSubscription.
type CreateSubscriptionJSONBody struct {
	AddressId openapi_types.UUID `json:"address_id"`
	PlanId    openapi_types.UUID `json:"plan_id"`

	// PromoCode A promo code typed at checkout. Case-insensitive.
	PromoCode *string `json:"promo_code,omitempty"`

	// PromoId A public offer from getKitchenOffers. Ignored when promo_code is set.
	PromoId *openapi_types.UUID `json:"promo_id,omitempty"`

	// RenewalMode `none` ends the subscription after one cycle — which is how a
	// trial is sold without building a trial feature.
	RenewalMode *CreateSubscriptionJSONBodyRenewalMode `json:"renewal_mode,omitempty"`
	Schedule    []struct {
		// AddressId Per-day override. Office Sunday to Thursday and home on
		// Friday is the normal case in this market, not an edge one.
		AddressId nullable.Nullable[openapi_types.UUID] `json:"address_id,omitempty"`

		// MealSlot `suhoor` and `iftar` are ordinary values, not exceptions.
		// Meal subscriptions invert during Ramadan and a schedule
		// that cannot express it is a month of undeliverable plans.
		MealSlot CreateSubscriptionJSONBodyScheduleMealSlot `json:"meal_slot"`

		// Weekday 0 = Sunday.
		Weekday  int                `json:"weekday"`
		WindowId openapi_types.UUID `json:"window_id"`
	} `json:"schedule"`
	SourceActionId nullable.Nullable[openapi_types.UUID] `json:"source_action_id,omitempty"`
	SourceReelId   nullable.Nullable[openapi_types.UUID] `json:"source_reel_id,omitempty"`
	StartDate      openapi_types.Date                    `json:"start_date"`

	// TierId Overrides the plan's price, days per week and meals per day.
	TierId nullable.Nullable[openapi_types.UUID] `json:"tier_id,omitempty"`
}

